const s = yield* search('task score priority');
yield* print(s);
yield* print(DOCS["skills/com.example.skill.score.md"]);

const Task = yield* Database.resolve('dxn:com.example.type.task:0.1.0');
const Score = yield* Database.resolve('dxn:com.example.operation.score');
const tasks = yield* Database.query(Filter.type(Task, { status: 'open' })).run;
const results = [];
for (const t of tasks) {
  const score = yield* Operation.invoke(Score, { title: t.title });
  Obj.update(t, (x) => { x.priority = score; });
  results.push({ id: t.id, title: t.title, score });
}
yield* Database.flush();
results.sort((a,b) => b.score - a.score);
yield* print(`open tasks: ${tasks.length}`);
yield* print(results);

